from __future__ import annotations
from dataclasses import dataclass
REVIEWED_PRIVATE_ADDITIONS = {'health.freshness': frozenset({'field_evidence'}), 'open_loops.items': frozenset({'last_reinforced_at', 'fading_presented_at', 'expired_at'})}

@dataclass(frozen=True)
class TablePolicy:
    name: str
    description: str
    database: str
    table: str
    expected_columns: tuple[str, ...]
    visible_columns: tuple[str, ...]
    id_columns: tuple[str, ...]
    text_columns: tuple[str, ...] = ()
    order_by: str | None = None

def _p(name: str, description: str, database: str, table: str, expected: str, visible: str, ids: str, *, text: str='', order_by: str | None=None) -> TablePolicy:
    split = lambda value: tuple((part for part in value.split() if part))
    policy = TablePolicy(name, description, database, table, split(expected), split(visible), split(ids), split(text), order_by)
    if not set(policy.visible_columns + policy.id_columns + policy.text_columns).issubset(policy.expected_columns):
        raise RuntimeError(f'invalid projection policy: {name}')
    return policy
